      SUBROUTINE FNDDEF(KNAME,IELEM)C---- DEAL WITH ELEMENT NAMELISTC-----------------------------------------------------------------------      CHARACTER*15    KNAME      INTEGER         IELEMC-----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1B.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATUM.CIN'      INCLUDE 'RDCARD.CIN'      INCLUDE 'RDWRDS.CIN'C-----------------------------------------------------------------------      REAL            FAKE      INTEGER         IDATA, IPDATA, II, LAKE, TEXT      EQUIVALENCE     (FAKE,LAKE)      EXTERNAL        TEXTCC---- PREVIOUS DEFINITION?C      CALL RDLOOK(KNAME,15,LABEL,1,NEL,IELEM)      IF (IELEM .EQ. 0) GO TO 100      II = ISTOR(IELEM)      IF (IDATA(II) .EQ. 24) GO TO 100      NEL = NEL + 1      ISTOR(NEL) = ISTOR(IELEM)      LABEL(NEL) = LABEL(IELEM)      NDESCR(NEL) = NDESCR(IELEM)      ISTOR(NEL+1) = I      GO TO 200CC---- NEW DEFINITION --- ALLOCATE ELEMENT CELLC  100 NDESC = 7      LABLE = KNAME      NWORD = 4      LAKE = 24      DATUM(1) = FAKE      LAKE = IPDATA(1)      DATUM(2) = FAKE      DATUM(3) = 0      DATUM(4) = 0      CALL ELSTORC  200 CONTINUE      RETURN      END